python3 -I -c 'exec('"'"'import json, statistics as S, sys
W = sys.argv[1] if len(sys.argv) > 1 else "study/results/removal_sample/runs"
names = [l.split("\t")[0] for l in open(W + "/pkgs24.tsv") if l.strip()]
def ld(d):
    try:
        return json.load(open(W + "/mig/" + d + "/summary.json"))
    except OSError:
        return None
def un(n):
    return next((s for s in (ld(p + n) for p in ("s2_", "c2_", "s_")) if s), None)
for lab, get in (("v14 defaults", lambda n: ld("v14_" + n)), ("no budget", un)):
    r = []
    for n in names:
        s = get(n)
        if s is None:
            continue
        t0, t1, db = s.get("time0") or {}, s.get("time1") or {}, s.get("default_build") or {}
        timed = bool(s.get("affected_modules")) and t0.get("rc") == 0 and t1.get("rc") == 0 and bool(t0.get("n_built"))
        r.append((n, s["native_axioms_before"], s["native_axioms_after"], timed, t0.get("wall"), t1.get("wall"), bool(s.get("build_ok")) and db.get("rc") == 0))
    a0, a1 = sum(x[1] for x in r), sum(x[2] for x in r)
    med = S.median([(x[1] - x[2]) / x[1] for x in r if x[1]])
    tm = [x for x in r if x[3] and x[4]]
    w = max(tm, key=lambda x: x[5] / x[4])
    print(f"{lab}: {len(r)} packages; native axioms removed {100 * (a0 - a1) / a0:.1f}% ({a0 - a1}/{a0}), median {100 * med:.1f}%; median wall ratio {S.median([x[5] / x[4] for x in tm]):.2f}; worst {w[5] / w[4]:.2f} ({w[0]}, {w[4]:.2f} -> {w[5]:.2f} s); more than twice as slow and 5 s longer: {sum(1 for x in tm if x[5] / x[4] > 2 and x[5] - x[4] > 5)} of {len(tm)}; builds ok {sum(1 for x in r if x[6])} of {len(r)}")
'"'"')'; grep '^| \*\*v14, defaults' study/results/removal_sample/budget_table.md | cut -d'|' -f2,6,7,12,13,14; sed -n '/^`migrate` rewrites/,/^$/p' README.md | tr '
' ' ' | tr -s ' ' | grep -o 'random sample of 24 packages with 1,472 native axioms\|the defaults removed 30% of them (median 25% per package), and no package.s build took more than 1.7 times as long (the slowest went from 1.03 to 1.74 s)\|it removed 54% (median 76%), but build time rose by a median factor of 1.9, and by up to 143.5 times\|In both runs 23 packages built afterwards'
